  console.log("poll status=" + jsonData.status + " want=" + __expected + " msLeft=" + (__deadline - Date.now()));
  rq.execution.setNextRequest(rq.execution.location.current);
} else {
  rq.environment.set("__pollDeadline", "");
  rq.test("Status da OS e " + __expected + " (timeout 3m)", function () {
    rq.expect(jsonData.status).to.equal(__expected);
  });
  rq.test("Id da OS confere", function () {
    rq.expect(String(jsonData.id)).to.equal(String(rq.environment.get("ordemServicoId")));
  });
