rq.test("WireMock journal 200", function () {
  rq.expect((rq.response.code != null ? rq.response.code : rq.response.status)).to.equal(200);
});
var journal = rq.response.json();
var ids = [];
(journal.requests || []).forEach(function (entry) {
  var req = entry.request || {};
  var method = String(req.method || "").toUpperCase();
  var url = String(req.url || "");
  if (method !== "POST") return;
  if (url.indexOf("/v1/orders") < 0 || url.indexOf("/cancel") >= 0) return;
  var bodyText = entry.response && entry.response.body;
  if (!bodyText) return;
  try {
    var body = typeof bodyText === "string" ? JSON.parse(bodyText) : bodyText;
    if (body && body.id && ids.indexOf(body.id) < 0) ids.push(String(body.id));
  } catch (e) {}
});
rq.test("WireMock registrou order id", function () {
  rq.expect(ids.length).to.be.above(0);
});
var orderId = ids[0];
rq.environment.set("dataId", orderId);
rq.environment.set("xRequestId", "req-requestly-e2e");

